struct uwbd_evt_type_handler {

	const char *name;

	struct uwbd_event *uwbd_events;

	size_t size;

};



/* Table of handlers for each UWBD Event type. */

static struct uwbd_evt_type_handler uwbd_urc_evt_type_handlers[] = {

	[UWB_RC_CET_GENERAL] = {

		.name        = "URC",

		.uwbd_events = uwbd_urc_events,

		.size        = ARRAY_SIZE(uwbd_urc_events),

	},

};



static const struct uwbd_event uwbd_message_handlers[] = {

	[UWB_EVT_MSG_RESET] = {

		.handler = uwbd_msg_handle_reset,

		.name = "reset",

	},

};



/*

 * Handle an URC event passed to the UWB Daemon

 *

 * @evt: the event to handle

 * @returns: 0 if the event can be kfreed, !0 on the contrary

 *           (somebody else took ownership) [coincidentally, returning

 *           a <0 errno code will free it :)].

 *

 * Looks up the two indirection tables (one for the type, one for the

 * subtype) to decide which function handles it and then calls the

 * handler.

 *

 * The event structure passed to the event handler has the radio

 * controller in @evt->rc referenced. The reference will be dropped

 * once the handler returns, so if it needs it for longer (async),

 * it'll need to take another one.

 */

static

int uwbd_event_handle_urc(struct uwb_event *evt)

{

	int result = -EINVAL;

	struct uwbd_evt_type_handler *type_table;

	uwbd_evt_handler_f handler;

	u8 type, context;

	u16 event;



	type = evt->notif.rceb->bEventType;

	event = le16_to_cpu(evt->notif.rceb->wEvent);

	context = evt->notif.rceb->bEventContext;



	if (type >= ARRAY_SIZE(uwbd_urc_evt_type_handlers))

		goto out;

	type_table = &uwbd_urc_evt_type_handlers[type];

	if (type_table->uwbd_events == NULL)

		goto out;

	if (event >= type_table->size)

		goto out;

	handler = type_table->uwbd_events[event].handler;

	if (handler == NULL)

		goto out;



	result = (*handler)(evt);

out:

	if (result < 0)

		dev_err(&evt->rc->uwb_dev.dev,

			"UWBD: event 0x%02x/%04x/%02x, handling failed: %d\n",

			type, event, context, result);

	return result;

}



static void uwbd_event_handle_message(struct uwb_event *evt)

{

	struct uwb_rc *rc;

	int result;



	rc = evt->rc;



	if (evt->message < 0 || evt->message >= ARRAY_SIZE(uwbd_message_handlers)) {

		dev_err(&rc->uwb_dev.dev, "UWBD: invalid message type %d\n", evt->message);

		return;

	}



	result = uwbd_message_handlers[evt->message].handler(evt);

	if (result < 0)

		dev_err(&rc->uwb_dev.dev, "UWBD: '%s' message failed: %d\n",

			uwbd_message_handlers[evt->message].name, result);

}



static void uwbd_event_handle(struct uwb_event *evt)

{

	struct uwb_rc *rc;

	int should_keep;



	rc = evt->rc;



	if (rc->ready) {

		switch (evt->type) {

		case UWB_EVT_TYPE_NOTIF:

			should_keep = uwbd_event_handle_urc(evt);

			if (should_keep <= 0)

				kfree(evt->notif.rceb);

			break;

		case UWB_EVT_TYPE_MSG:

			uwbd_event_handle_message(evt);

			break;

		default:

			dev_err(&rc->uwb_dev.dev, "UWBD: invalid event type %d\n", evt->type);

			break;

		}

	}



	__uwb_rc_put(rc);	/* for the __uwb_rc_get() in uwb_rc_notif_cb() */

}



/**

 * UWB Daemon

 *

 * Listens to all UWB notifications and takes care to track the state

 * of the UWB neighbourhood for the kernel. When we do a run, we

 * spinlock, move the list to a private copy and release the

 * lock. Hold it as little as possible. Not a conflict: it is

 * guaranteed we own the events in the private list.

 *

 * FIXME: should change so we don't have a 1HZ timer all the time, but

 *        only if there are devices.

 */

static int uwbd(void *param)

{

	struct uwb_rc *rc = param;

	unsigned long flags;

	struct uwb_event *evt;

	int should_stop = 0;



	while (1) {

		wait_event_interruptible_timeout(

			rc->uwbd.wq,

			!list_empty(&rc->uwbd.event_list)

			  || (should_stop = kthread_should_stop()),

			HZ);

		if (should_stop)

			break;



		spin_lock_irqsave(&rc->uwbd.event_list_lock, flags);

		if (!list_empty(&rc->uwbd.event_list)) {

			evt = list_first_entry(&rc->uwbd.event_list, struct uwb_event, list_node);

			list_del(&evt->list_node);

		} else

			evt = NULL;

		spin_unlock_irqrestore(&rc->uwbd.event_list_lock, flags);



		if (evt) {

			uwbd_event_handle(evt);

			kfree(evt);

		}



		uwb_beca_purge(rc);	/* Purge devices that left */

	}

	return 0;

}





/** Start the UWB daemon */

void uwbd_start(struct uwb_rc *rc)

{

	rc->uwbd.task = kthread_run(uwbd, rc, "uwbd");

	if (rc->uwbd.task == NULL)

		printk(KERN_ERR "UWB: Cannot start management daemon; "

		       "UWB won't work\n");

	else

		rc->uwbd.pid = rc->uwbd.task->pid;

}



/* Stop the UWB daemon and free any unprocessed events */

void uwbd_stop(struct uwb_rc *rc)

{

	kthread_stop(rc->uwbd.task);

	uwbd_flush(rc);

}



/*

 * Queue an event for the management daemon

 *

 * When some lower layer receives an event, it uses this function to

 * push it forward to the UWB daemon.

 *

 * Once you pass the event, you don't own it any more, but the daemon

 * does. It will uwb_event_free() it when done, so make sure you

 * uwb_event_alloc()ed it or bad things will happen.

 *

 * If the daemon is not running, we just free the event.

 */

void uwbd_event_queue(struct uwb_event *evt)

{

	struct uwb_rc *rc = evt->rc;

	unsigned long flags;



	spin_lock_irqsave(&rc->uwbd.event_list_lock, flags);

	if (rc->uwbd.pid != 0) {

		list_add(&evt->list_node, &rc->uwbd.event_list);

		wake_up_all(&rc->uwbd.wq);

	} else {

		__uwb_rc_put(evt->rc);

		if (evt->type == UWB_EVT_TYPE_NOTIF)

			kfree(evt->notif.rceb);

		kfree(evt);

	}

	spin_unlock_irqrestore(&rc->uwbd.event_list_lock, flags);

	return;

}



void uwbd_flush(struct uwb_rc *rc)

{

	struct uwb_event *evt, *nxt;



	spin_lock_irq(&rc->uwbd.event_list_lock);

	list_for_each_entry_safe(evt, nxt, &rc->uwbd.event_list, list_node) {

		if (evt->rc == rc) {

			__uwb_rc_put(rc);

			list_del(&evt->list_node);

			if (evt->type == UWB_EVT_TYPE_NOTIF)

				kfree(evt->notif.rceb);

			kfree(evt);

		}

	}

	spin_unlock_irq(&rc->uwbd.event_list_lock);

}

