    const char *opcode;

    const char *sender;

    const char *recipient;

    const char *format;

    int cksum;

    int multi;

    const char *multi_uid;

    /* Other fields follow here.. */

};



enum z_packet_type {

    Z_PACKET_UNSAFE = 0,

    Z_PACKET_UNACKED,

    Z_PACKET_ACKED,

    Z_PACKET_HMACK,

    Z_PACKET_HMCTL,

    Z_PACKET_SERVACK,

    Z_PACKET_SERVNAK,

    Z_PACKET_CLIENTACK,

    Z_PACKET_STAT

};



static const struct tok z_types[] = {

    { Z_PACKET_UNSAFE,		"unsafe" },

    { Z_PACKET_UNACKED,		"unacked" },

    { Z_PACKET_ACKED,		"acked" },

    { Z_PACKET_HMACK,		"hm-ack" },

    { Z_PACKET_HMCTL,		"hm-ctl" },

    { Z_PACKET_SERVACK,		"serv-ack" },

