//***********************************

// interface bandwidth linked list

//***********************************

typedef struct ifbw_t {

	struct ifbw_t *next;

	char *txt;

} IFBW;

IFBW *ifbw = NULL;





#if 0

static void ifbw_print(void) {

	IFBW *ptr = ifbw;

	while (ptr) {

		printf("#%s#\n", ptr->txt);

		ptr = ptr->next;

	}

}

#endif



static void ifbw_add(IFBW *ptr) {

	assert(ptr);



	if (ifbw != NULL)

		ptr->next = ifbw;

	ifbw = ptr;

}





IFBW *ifbw_find(const char *dev) {

	assert(dev);

	int len = strlen(dev);

	assert(len);



	if (ifbw == NULL)

		return NULL;



	IFBW *ptr = ifbw;

	while (ptr) {

		if (strncmp(ptr->txt, dev, len) == 0 && ptr->txt[len] == ':')

			return ptr;

		ptr = ptr->next;

	}



	return NULL;

}



void ifbw_remove(IFBW *r) {

	if (ifbw == NULL)

		return;



	// remove the first element

	if (ifbw == r) {

		ifbw = ifbw->next;

		return;

	}



	// walk the list

	IFBW *ptr = ifbw->next;

	IFBW *prev = ifbw;

	while (ptr) {

		if (ptr == r) {

			prev->next = ptr->next;

			return;

		}



		prev = ptr;

		ptr = ptr->next;

	}	



	return;

}



int fibw_count(void) {

	int rv = 0;

	IFBW *ptr = ifbw;



	while (ptr) {

		rv++;

		ptr = ptr->next;

	}



	return rv;

}





