static void sig_server_connect_copy(SERVER_CONNECT_REC **dest,

				    IRC_SERVER_CONNECT_REC *src)

{

	IRC_SERVER_CONNECT_REC *rec;



	g_return_if_fail(dest != NULL);

	if (!IS_IRC_SERVER_CONNECT(src))

		return;



	rec = g_new0(IRC_SERVER_CONNECT_REC, 1);

	rec->chat_type = IRC_PROTOCOL;

	rec->max_cmds_at_once = src->max_cmds_at_once;

	rec->cmd_queue_speed = src->cmd_queue_speed;

        rec->max_query_chans = src->max_query_chans;

	rec->max_kicks = src->max_kicks;

	rec->max_modes = src->max_modes;

	rec->max_msgs = src->max_msgs;

	rec->max_whois = src->max_whois;

	rec->usermode = g_strdup(src->usermode);

	rec->alternate_nick = g_strdup(src->alternate_nick);

	rec->sasl_mechanism = src->sasl_mechanism;

	rec->sasl_username = src->sasl_username;

	rec->sasl_password = src->sasl_password;

	*dest = (SERVER_CONNECT_REC *) rec;

}



static void sig_server_reconnect_save_status(IRC_SERVER_CONNECT_REC *conn,

					     IRC_SERVER_REC *server)

{

	if (!IS_IRC_SERVER_CONNECT(conn) || !IS_IRC_SERVER(server) ||

	    !server->connected)

		return;



	g_free_not_null(conn->channels);

	conn->channels = irc_server_get_channels(server);



	g_free_not_null(conn->usermode);

	conn->usermode = g_strdup(server->wanted_usermode);

}



static void sig_connected(IRC_SERVER_REC *server)

{

	if (!IS_IRC_SERVER(server) || !server->connrec->reconnection)

		return;



	if (server->connrec->away_reason != NULL)

		irc_server_send_away(server, server->connrec->away_reason);

}



static void event_nick_collision(IRC_SERVER_REC *server, const char *data)

{

	time_t new_connect;



	if (!IS_IRC_SERVER(server))

		return;



	/* after server kills us because of nick collision, we want to

	   connect back immediately. but no matter how hard they kill us,

	   don't connect to the server more than once in every 10 seconds. */



	new_connect = server->connect_time+10 -

		settings_get_time("server_reconnect_time")/1000;

	if (server->connect_time > new_connect)

		server->connect_time = new_connect;



        server->nick_collision = TRUE;

}



static void event_kill(IRC_SERVER_REC *server, const char *data,

		       const char *nick, const char *addr)

{

	if (addr != NULL && !server->nick_collision) {

		/* don't reconnect if we were killed by an oper (not server) */

		server->no_reconnect = TRUE;

	}

}



void irc_servers_reconnect_init(void)

{

	signal_add("server connect copy", (SIGNAL_FUNC) sig_server_connect_copy);

	signal_add("server reconnect save status", (SIGNAL_FUNC) sig_server_reconnect_save_status);

	signal_add("event connected", (SIGNAL_FUNC) sig_connected);

	signal_add("event 436", (SIGNAL_FUNC) event_nick_collision);

	signal_add("event kill", (SIGNAL_FUNC) event_kill);

}



void irc_servers_reconnect_deinit(void)

{

	signal_remove("server connect copy", (SIGNAL_FUNC) sig_server_connect_copy);

	signal_remove("server reconnect save status", (SIGNAL_FUNC) sig_server_reconnect_save_status);

	signal_remove("event connected", (SIGNAL_FUNC) sig_connected);

	signal_remove("event 436", (SIGNAL_FUNC) event_nick_collision);

	signal_remove("event kill", (SIGNAL_FUNC) event_kill);

}

#include <stdlib.h>

#include <stdio.h>

#include <ctype.h>

#include <string.h>



#include "../common/cmdline.h"



#define TAG FREERDP_TAG("generate_argument_docbook")

LPSTR tr_esc_str(LPCSTR arg, bool format)

{

	LPSTR tmp = NULL;

	LPSTR tmp2 = NULL;

	size_t cs = 0, x, ds, len;

	size_t s;



	if (NULL == arg)

		return NULL;



	s = strlen(arg);



	/* Find trailing whitespaces */

	while ((s > 0) && isspace(arg[s - 1]))

		s--;



	/* Prepare a initial buffer with the size of the result string. */

	ds = s + 1;



	if (s)

	{

		tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

		if (!tmp2)

			free(tmp);

		tmp = tmp2;

	}



	if (NULL == tmp)

	{

		fprintf(stderr,  "Could not allocate string buffer.\n");

		exit(-2);

	}



	/* Copy character for character and check, if it is necessary to escape. */

	memset(tmp, 0, ds * sizeof(CHAR));



	for (x = 0; x < s; x++)

	{

		switch (arg[x])

		{

			case '<':

				len = format ? 13 : 4;

				ds += len - 1;

				tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

				if (!tmp2)

					free(tmp);

				tmp = tmp2;



				if (NULL == tmp)

				{

					fprintf(stderr,  "Could not reallocate string buffer.\n");

					exit(-3);

				}



				if (format)

					/* coverity[buffer_size] */

					strncpy(&tmp[cs], "<replaceable>", len);

				else

					/* coverity[buffer_size] */

					strncpy(&tmp[cs], "&lt;", len);



				cs += len;

				break;



			case '>':

				len = format ? 14 : 4;

				ds += len - 1;

				tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

				if (!tmp2)

					free(tmp);

				tmp = tmp2;



				if (NULL == tmp)

				{

					fprintf(stderr,  "Could not reallocate string buffer.\n");

					exit(-4);

				}



				if (format)

					/* coverity[buffer_size] */

					strncpy(&tmp[cs], "</replaceable>", len);

				else

					/* coverity[buffer_size] */

					strncpy(&tmp[cs], "&lt;", len);



				cs += len;

				break;



			case '\'':

				ds += 5;

				tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

				if (!tmp2)

					free(tmp);

				tmp = tmp2;



				if (NULL == tmp)

				{

					fprintf(stderr,  "Could not reallocate string buffer.\n");

					exit(-5);

				}



				tmp[cs++] = '&';

				tmp[cs++] = 'a';

				tmp[cs++] = 'p';

				tmp[cs++] = 'o';

				tmp[cs++] = 's';

				tmp[cs++] = ';';

				break;



			case '"':

				ds += 5;

				tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

				if (!tmp2)

					free(tmp);

				tmp = tmp2;



				if (NULL == tmp)

				{

					fprintf(stderr,  "Could not reallocate string buffer.\n");

					exit(-6);

				}



				tmp[cs++] = '&';

				tmp[cs++] = 'q';

				tmp[cs++] = 'u';

				tmp[cs++] = 'o';

				tmp[cs++] = 't';

				tmp[cs++] = ';';

				break;



			case '&':

				ds += 4;

				tmp2 = (LPSTR)realloc(tmp, ds * sizeof(CHAR));

				if (!tmp2)

					free(tmp);

				tmp = tmp2;



				if (NULL == tmp)

				{

					fprintf(stderr,  "Could not reallocate string buffer.\n");

					exit(-7);

				}



				tmp[cs++] = '&';

				tmp[cs++] = 'a';

				tmp[cs++] = 'm';

				tmp[cs++] = 'p';

				tmp[cs++] = ';';

				break;



			default:

				tmp[cs++] = arg[x];

				break;

		}



		/* Assure, the string is '\0' terminated. */

		tmp[ds - 1] = '\0';

	}



	return tmp;

}



int main(int argc, char* argv[])

{

	size_t elements = sizeof(args) / sizeof(args[0]);

	size_t x;

	const char* fname = "xfreerdp-argument.1.xml";

	FILE* fp = NULL;

	/* Open output file for writing, truncate if existing. */

	fp = fopen(fname, "w");



	if (NULL == fp)

	{

		fprintf(stderr,  "Could not open '%s' for writing.\n", fname);

		return -1;

	}



	/* The tag used as header in the manpage */

	fprintf(fp, "<refsect1>\n");

	fprintf(fp, "\t<title>Options</title>\n");

	fprintf(fp, "\t\t<variablelist>\n");



	/* Iterate over argument struct and write data to docbook 4.5

	 * compatible XML */

	if (elements < 2)

	{

		fprintf(stderr,  "The argument array 'args' is empty, writing an empty file.\n");

		elements = 1;

	}



	for (x = 0; x < elements - 1; x++)

	{

		const COMMAND_LINE_ARGUMENT_A* arg = &args[x];

		char* name = tr_esc_str((LPSTR) arg->Name, FALSE);

		char* alias = tr_esc_str((LPSTR) arg->Alias, FALSE);

		char* format = tr_esc_str(arg->Format, TRUE);

		char* text = tr_esc_str((LPSTR) arg->Text, FALSE);

		fprintf(fp, "\t\t\t<varlistentry>\n");



		do

		{

			fprintf(fp, "\t\t\t\t<term><option>");



			if (arg->Flags == COMMAND_LINE_VALUE_BOOL)

				fprintf(fp, "%s", arg->Default ? "-" : "+");

			else

				fprintf(fp, "/");



			fprintf(fp, "%s</option>", name);



			if (format)

			{

				if (arg->Flags == COMMAND_LINE_VALUE_OPTIONAL)

					fprintf(fp, "[");



				fprintf(fp, ":%s", format);



				if (arg->Flags == COMMAND_LINE_VALUE_OPTIONAL)

					fprintf(fp, "]");

			}



			fprintf(fp, "</term>\n");



			if (alias == name)

				break;



			free(name);

			name = alias;

		}

		while (alias);



		if (text)

		{

			fprintf(fp, "\t\t\t\t<listitem>\n");

			fprintf(fp, "\t\t\t\t\t<para>");



			if (text)

				fprintf(fp, "%s", text);



			if (arg->Flags == COMMAND_LINE_VALUE_BOOL)

				fprintf(fp, " (default:%s)", arg->Default ? "on" : "off");

			else if (arg->Default)

			{

				char* value = tr_esc_str((LPSTR) arg->Default, FALSE);

				fprintf(fp, " (default:%s)", value);

				free(value);

			}



			fprintf(fp, "</para>\n");

			fprintf(fp, "\t\t\t\t</listitem>\n");

		}



		fprintf(fp, "\t\t\t</varlistentry>\n");

		free(name);

		free(format);

		free(text);

	}



	fprintf(fp, "\t\t</variablelist>\n");

	fprintf(fp, "\t</refsect1>\n");

	fclose(fp);

	return 0;

}

