/*

 * Extract a tag from the line.

 *

 * Return 1 if a valid tag was found.

 * Return 0 if no tag found.

 * Return -ve error code.

 */

static int parse_tag(blkid_cache cache, blkid_dev dev, char **cp)

{

	char *name = NULL;

	char *value = NULL;

	int ret;



	if (!cache || !dev)

		return -BLKID_ERR_PARAM;



	if ((ret = parse_token(&name, &value, cp)) <= 0 /* &&

	    (ret = parse_xml(&name, &value, cp)) <= 0 */)

		return ret;



	/* Some tags are stored directly in the device struct */

	if (!strcmp(name, "DEVNO"))

		dev->bid_devno = STRTOULL(value, 0, 0);

	else if (!strcmp(name, "PRI"))

		dev->bid_pri = strtol(value, 0, 0);

	else if (!strcmp(name, "TIME")) {

		char *end = NULL;

		dev->bid_time = STRTOULL(value, &end, 0);

		if (end && *end == '.')

			dev->bid_utime = STRTOULL(end + 1, 0, 0);

	} else

		ret = blkid_set_tag(dev, name, value, strlen(value));



	DBG(READ, ul_debug("    tag: %s=\"%s\"", name, value));



	return ret < 0 ? ret : 1;

}



/*

 * Parse a single line of data, and return a newly allocated dev struct.

 * Add the new device to the cache struct, if one was read.

 *

 * Lines are of the form <device [TAG="value" ...]>/dev/foo</device>

 *

 * Returns -ve value on error.

 * Returns 0 otherwise.

 * If a valid device was read, *dev_p is non-NULL, otherwise it is NULL

 * (e.g. comment lines, unknown XML content, etc).

 */

static int blkid_parse_line(blkid_cache cache, blkid_dev *dev_p, char *cp)

{

	blkid_dev dev;

	int ret;



	if (!cache || !dev_p)

		return -BLKID_ERR_PARAM;



	*dev_p = NULL;



	DBG(READ, ul_debug("line: %s", cp));



	if ((ret = parse_dev(cache, dev_p, &cp)) <= 0)

		return ret;



	dev = *dev_p;



	while ((ret = parse_tag(cache, dev, &cp)) > 0) {

		;

	}



	if (dev->bid_type == NULL) {

		DBG(READ, ul_debug("blkid: device %s has no TYPE",dev->bid_name));

		blkid_free_dev(dev);

		goto done;

	}



	DBG(READ, blkid_debug_dump_dev(dev));



done:

	return ret;

}



/*

 * Parse the specified filename, and return the data in the supplied or

 * a newly allocated cache struct.  If the file doesn't exist, return a

 * new empty cache struct.

 */

void blkid_read_cache(blkid_cache cache)

{

	FILE *file;

	char buf[4096];

	int fd, lineno = 0;

	struct stat st;



	if (!cache)

		return;



	/*

	 * If the file doesn't exist, then we just return an empty

	 * struct so that the cache can be populated.

	 */

	if ((fd = open(cache->bic_filename, O_RDONLY|O_CLOEXEC)) < 0)

		return;

	if (fstat(fd, &st) < 0)

		goto errout;

	if ((st.st_mtime == cache->bic_ftime) ||

	    (cache->bic_flags & BLKID_BIC_FL_CHANGED)) {

		DBG(CACHE, ul_debug("skipping re-read of %s",

					cache->bic_filename));

		goto errout;

	}



	DBG(CACHE, ul_debug("reading cache file %s",

				cache->bic_filename));



	file = fdopen(fd, "r" UL_CLOEXECSTR);

	if (!file)

		goto errout;



	while (fgets(buf, sizeof(buf), file)) {

		blkid_dev dev;

		unsigned int end;



		lineno++;

		if (buf[0] == 0)

			continue;

		end = strlen(buf) - 1;

		/* Continue reading next line if it ends with a backslash */

		while (end < (sizeof(buf) - 2) && buf[end] == '\\' &&

		       fgets(buf + end, sizeof(buf) - end, file)) {

			end = strlen(buf) - 1;

			lineno++;

		}



		if (blkid_parse_line(cache, &dev, buf) < 0) {

			DBG(READ, ul_debug("blkid: bad format on line %d", lineno));

			continue;

		}

	}

	fclose(file);



	/*

	 * Initially we do not need to write out the cache file.

	 */

	cache->bic_flags &= ~BLKID_BIC_FL_CHANGED;

	cache->bic_ftime = st.st_mtime;



	return;

errout:

	close(fd);

	return;

}



