int main( void )

{

    unsigned rv = 1;

    CU_pSuite suite = NULL;



    if( CUE_SUCCESS == CU_initialize_registry() ) {

        add_suites( &suite );



        if( NULL != suite ) {

            CU_basic_set_mode( CU_BRM_VERBOSE );

            CU_basic_run_tests();

            printf ( "\n" );

            CU_basic_show_failures( CU_get_failure_list() );

            printf ( "\n\n" );

            rv = CU_get_number_of_tests_failed();

        }



        CU_cleanup_registry();



    }



    return rv;

}

